import{_ as r,C as s,o as n,c as l,ag as o,E as a}from"./chunks/framework.CtWPcAmt.js";const f=JSON.parse('{"title":"Product Form Layout","description":"","frontmatter":{},"headers":[],"relativePath":"catalog/product-form-layout.md","filePath":"catalog/product-form-layout.md","lastUpdated":1787558413000}'),i={name:"catalog/product-form-layout.md"};function g(p,t,h,d,u,c){const e=s("ImagePopup");return n(),l("div",null,[t[0]||(t[0]=o('<h1 id="product-form-layout" tabindex="-1">Product Form Layout <a class="header-anchor" href="#product-form-layout" aria-label="Permalink to &quot;Product Form Layout&quot;">​</a></h1><p>The seller product form doesn&#39;t have to look the same for every kind of product. Product Form Layout lets the admin choose the shape of that form — stepped or two-column — globally and then per attribute family, along with the order of the steps and how a seller moves between them.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>The global product form settings</li><li>How to override the layout for one attribute family</li><li>What each layout and navigation option looks like to a seller</li></ul></div><div class="tip custom-block"><p class="custom-block-title">This changes only the seller&#39;s form</p><p>The admin product form is unaffected by everything on this page. See <a href="/catalog/product-management#the-product-form">Product Management</a> for the form as a seller meets it.</p></div><h2 id="the-global-setting" tabindex="-1">The global setting <a class="header-anchor" href="#the-global-setting" aria-label="Permalink to &quot;The global setting&quot;">​</a></h2><p>Go to <strong>Configure → Marketplace → Products → Product Form</strong>:</p><ul><li><strong>Enable Stepped Product Form</strong> — on, sellers get the step-by-step form; off, they get the classic two-column form.</li><li><strong>Stepped Form Navigation</strong> — how a seller moves between steps: <strong>Horizontal</strong> shows a scrolling tab strip, <strong>Vertical</strong> shows a side rail with every step visible on wide screens.</li><li><strong>Show Progress Bar</strong> — whether the stepped form shows how far through the seller is.</li></ul><p>This is the default every attribute family follows unless it&#39;s given its own.</p><h2 id="per-family-overrides" tabindex="-1">Per-family overrides <a class="header-anchor" href="#per-family-overrides" aria-label="Permalink to &quot;Per-family overrides&quot;">​</a></h2><p>Go to <strong>Marketplace → Catalog → Product Form</strong>. Each row is an <strong>Attribute Family</strong>, showing the <strong>Layout</strong> and <strong>Navigation</strong> it currently uses, with a <strong>Configure</strong> action — the pencil under <strong>Actions</strong> — to change them.</p>',10)),a(e,{src:"/images/product-form-layout/form-layout-list.png",alt:"Product Form Layout list showing each attribute family with its layout and navigation"}),t[1]||(t[1]=o('<p>Select several families with the checkboxes to apply <strong>Update Layout</strong> or <strong>Update Navigation</strong> across the selection in one move.</p><h2 id="configuring-one-family" tabindex="-1">Configuring one family <a class="header-anchor" href="#configuring-one-family" aria-label="Permalink to &quot;Configuring one family&quot;">​</a></h2><p><strong>Configure</strong> opens that family&#39;s settings:</p><p><strong>Form Layout:</strong> <strong>Inherit (Global)</strong>, <strong>Stepped</strong>, or <strong>Two Column</strong>. Choosing Inherit tells you which layout the global setting currently resolves to, so you can see what the family will actually get.</p><p><strong>Step Order:</strong> Drag the attribute-group steps into the order sellers should meet them.</p><p><strong>Step Navigation:</strong> <strong>Inherit (Global)</strong>, <strong>Horizontal Tabs</strong>, or <strong>Vertical Rail</strong>.</p>',6)),a(e,{src:"/images/product-form-layout/form-layout-configure.png",alt:"Configuring one family — draggable step order beside the Form Layout and Step Navigation selects"}),t[2]||(t[2]=o('<p>Save, and every seller creating or editing a product in that family gets the form you&#39;ve described.</p><h3 id="step-order-and-navigation-apply-only-to-the-stepped-form" tabindex="-1">Step order and navigation apply only to the stepped form <a class="header-anchor" href="#step-order-and-navigation-apply-only-to-the-stepped-form" aria-label="Permalink to &quot;Step order and navigation apply only to the stepped form&quot;">​</a></h3><p>Both settings are disabled when the layout is <strong>Two Column</strong>, because a two-column form has no steps to order or navigate between. Switch the layout back to <strong>Stepped</strong> — or to <strong>Inherit</strong> where the global setting is stepped — and they become editable again.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Put the steps a seller can answer without leaving the room first — the basics and the price — and the ones needing photographs or measurements last. A family whose first step is easy gets far fewer abandoned <a href="/catalog/draft-products">drafts</a>.</p></div>',4))])}const y=r(i,[["render",g]]);export{f as __pageData,y as default};
